/* An archived product is never also published. A product has a status (draft, published, archived) and, from an older migration, an archived flag; every page that shows or sells a product asks for status = 'published', so the two have to agree or an archived product stays on sale. Archive writes both and publishing clears the flag, but that was two writes from the browser, and one that failed left a product published and archived at once: on the creator's page and in checkout, while the Products list said Archived. A trigger keeps them in step from now on: status archived sets the flag; publishing a product (its status changed to published) clears the flag; setting the flag on a published product archives it. Then one pass over the products that are published and flagged now (the same pass part 08 made; there were none last time). Changes no other rows. Skips itself where products has no archived column. Run after 08. Until it runs, the app writes both marks as before and reads the flag where it can. */
CREATE OR REPLACE FUNCTION public.products_keep_archive_in_step() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $fn$ BEGIN IF NEW.status = 'archived' THEN NEW.archived := true; ELSIF NEW.archived IS TRUE AND NEW.status = 'published' THEN IF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM 'published' THEN NEW.archived := false; ELSE NEW.status := 'archived'; END IF; END IF; RETURN NEW; END $fn$;
REVOKE ALL ON FUNCTION public.products_keep_archive_in_step() FROM PUBLIC, anon, authenticated;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'products' AND column_name = 'archived') THEN RAISE NOTICE 'products has no archived column here: the trigger is not needed and was not made'; RETURN; END IF; DROP TRIGGER IF EXISTS products_keep_archive_in_step ON public.products; CREATE TRIGGER products_keep_archive_in_step BEFORE INSERT OR UPDATE OF status, archived ON public.products FOR EACH ROW EXECUTE FUNCTION public.products_keep_archive_in_step(); UPDATE public.products SET status = 'archived' WHERE archived IS TRUE AND status = 'published'; END $$;
notify pgrst, 'reload schema';
